(7398132, 1164201, 30982, '<td valign="top">Ha!  Now here''s a great snapshot - flash, failure to rotate, questionable composition.  Well done!</td>', 'Ha!  Now here''s a great snapshot - flash, failure to rotate, questionable composition.  Well done!', '2015-08-17 23:06:55.000000', NULL, 1),
